if (shippingAddress.first_name || shippingAddress.last_name) {
  fullAddress += `${shippingAddress.first_name || ''} ${shippingAddress.last_name || ''}`;
}

let addressLine = '';
if (shippingAddress.address_1) {
  addressLine += shippingAddress.address_1;
}
if (shippingAddress.address_2) {
  addressLine += `, ${shippingAddress.address_2}`;
}
if (addressLine) {
  fullAddress += `\n${addressLine}`;
}

let cityStatePostcode = '';
if (shippingAddress.city) {
  cityStatePostcode += shippingAddress.city;
}
if (shippingAddress.state) {
  if (cityStatePostcode) cityStatePostcode += ', ';
  cityStatePostcode += shippingAddress.state;
}
if (shippingAddress.postcode) {
  fullAddress += `\n${cityStatePostcode}, ${shippingAddress.postcode}`;
}
else if (cityStatePostcode) {
  fullAddress += `\n${cityStatePostcode}`;
}

if (shippingAddress.country) {
  fullAddress += `\n${shippingAddress.country}`;
}

