  // Continue, but metadata might be incomplete. The filename might be reconstructed from slipOrderId if necessary.
}


if (!slipOrderId || !orderData || !orderData.id) {
    console.error("Critical data (slipOrderId or orderData.id) missing in input for 'Add to Batch'. Input JSON:", JSON.stringify($json));
}

try {
