// Step 1: Read the batch file containing Google Drive IDs
const fs = require('fs');
const path = require('path');

const today = new Date().toISOString().split('T')[0];
const shippingSlipsDir = './shipping_slips'; // Local directory for batch control files
const batchFilePath = path.join(shippingSlipsDir, `batch_gdrive_ids_${today}.txt`);

let googleDriveFileIds = [];
let statusMessage = '';

if (!fs.existsSync(batchFilePath)) {
  statusMessage = 'No batch file found for today.';
  return [{ json: { status: statusMessage, processed: false, batchFilePath, googleDriveFileIds } }];
}

const fileContent = fs.readFileSync(batchFilePath, 'utf8').trim();
if (fileContent === '') {
  statusMessage = 'Batch file is empty.';
  return [{ json: { status: statusMessage, processed: false, batchFilePath, googleDriveFileIds } }];
}

googleDriveFileIds = fileContent.split('\n').filter(id => id.trim() !== '');

if (googleDriveFileIds.length === 0) {
  statusMessage = 'No Google Drive File IDs found in batch file.';
  return [{ json: { status: statusMessage, processed: false, batchFilePath, googleDriveFileIds } }];
}

// Return each ID as a separate item for looping
return googleDriveFileIds.map(id => ({ 
  json: { 
    googleDriveFileId: id,
    today: today, // Pass along for consistent naming
    batchFilePath: batchFilePath // Pass along for potential cleanup later
  } 
}));

const fs = require('fs');
const path = require('path');
const { PDFDocument } = require('pdf-lib');

// items will be an array of objects, each from an iteration of "Save Temporary PDF Locally"
// Each item should have a property (e.g., 'filePath' or 'fileName') that gives the path to the temp PDF.
// Let's assume the WriteBinaryFile node outputs the path in a property 'filePath'.
// If it's different (e.g. 'fileName' if it's just the name, or might be nested), this needs adjustment.
// The input to WriteBinaryFile ('Save Temporary PDF Locally') was $json.googleDriveFileId.
// So, this function node will receive an array like:
// [ { json: { googleDriveFileId: 'id1', ...other data from loop... } }, { json: { googleDriveFileId: 'id2', ... } } ]
// The temporary file paths were './shipping_slips/temp/' + googleDriveFileId + '.pdf'

async function processAndCombine() {
  const compiledPdfDir = './shipping_slips';
  const tempDir = path.join(compiledPdfDir, 'temp');
  const today = items[0]?.json?.today || new Date().toISOString().split('T')[0]; // Get 'today' from first item or generate

  const compiledPdfPath = path.join(compiledPdfDir, `compiled_slips_gdrive_${today}.pdf`);

  const sourcePdfPaths = [];
  for (const item of items) {
    const tempPdfPath = path.join(tempDir, `${item.json.googleDriveFileId}.pdf`);
    if (fs.existsSync(tempPdfPath)) {
      sourcePdfPaths.push(tempPdfPath);
    } else {
      console.warn(`Temporary PDF not found: ${tempPdfPath}`);
    }
  }

  if (sourcePdfPaths.length === 0) {
    return [{ json: { status: 'No temporary PDFs found to combine.', processed: false, sourcePdfPaths } }];
  }

  try {
    const combinedPdf = await PDFDocument.create();
    for (const pdfPath of sourcePdfPaths) {
      try {
        const pdfBytes = fs.readFileSync(pdfPath);
        const pdfDoc = await PDFDocument.load(pdfBytes);
        const copiedPages = await combinedPdf.copyPages(pdfDoc, pdfDoc.getPageIndices());
        copiedPages.forEach(page => combinedPdf.addPage(page));
      } catch (loadErr) {
        console.error(`Error processing temporary PDF ${pdfPath}:`, loadErr);
      }
    }

    if (combinedPdf.getPageCount() === 0) {
      return [{ json: { status: 'Failed to combine any pages from temporary PDFs.', processed: false, sourcePdfPaths } }];
    }

    const combinedPdfBytes = await combinedPdf.save();
    fs.writeFileSync(compiledPdfPath, combinedPdfBytes);

    // Optional: Cleanup temporary files
    for (const pdfPath of sourcePdfPaths) {
      try {
        fs.unlinkSync(pdfPath);
      } catch (unlinkErr) {
        console.warn(`Failed to delete temporary file ${pdfPath}:`, unlinkErr);
      }
    }
    // Optional: Cleanup batch file (batchFilePath was passed in each item from 'Read Google Drive IDs Batch File')
    const batchFilePath = items[0]?.json?.batchFilePath;
    if (batchFilePath && fs.existsSync(batchFilePath)) {
      try {
         // fs.unlinkSync(batchFilePath); // Uncomment to delete batch file
         console.log(`Batch file ${batchFilePath} processed. Ready for cleanup.`);
      } catch (e) { console.warn(`Could not cleanup batch file ${batchFilePath}`)}
    }

    return [{ json: { 
      status: 'Batch PDF from Google Drive files successfully created.', 
      outputPath: compiledPdfPath, 
      processedPdfCount: sourcePdfPaths.length,
      processed: true 
    }}];

  } catch (error) {
    console.error('Error during PDF combination from temporary files:', error);
    return [{ json: { status: 'Error combining PDFs.', error: error.message, errorStack: error.stack, processed: false } }];
  }
}

return await processAndCombine();
